ALTER TABLE public.user_roles ADD COLUMN IF NOT EXISTS is_superadmin boolean NOT NULL DEFAULT false;
INSERT INTO public.user_roles(user_id, role, is_superadmin) SELECT p.user_id, 'admin'::public.app_role, true FROM public.profiles p WHERE p.is_superadmin ON CONFLICT (user_id,role) DO UPDATE SET is_superadmin=true;
CREATE OR REPLACE FUNCTION private.is_superadmin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND is_superadmin) $$;
CREATE OR REPLACE FUNCTION public.is_access_superadmin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_superadmin() $$;
REVOKE ALL ON FUNCTION public.is_access_superadmin() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_access_superadmin() TO authenticated,service_role;
CREATE TABLE public.user_company_permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'CONSULTOR' CHECK(role IN ('CLIENTE','CONSULTOR','GESTOR','SUPERADMIN')), permissions jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,company_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_company_permissions TO authenticated;
GRANT ALL ON public.user_company_permissions TO service_role;
ALTER TABLE public.user_company_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY permissions_self_read ON public.user_company_permissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR private.is_superadmin());
CREATE POLICY permissions_admin_write ON public.user_company_permissions FOR ALL TO authenticated USING(private.is_superadmin()) WITH CHECK(private.is_superadmin());
INSERT INTO public.user_company_permissions(user_id,company_id,role,permissions) SELECT user_id,company_id,CASE WHEN member_role='gestor' THEN 'GESTOR' WHEN member_role='cliente' THEN 'CLIENTE' ELSE 'CONSULTOR' END,permissions FROM public.company_members ON CONFLICT(user_id,company_id) DO NOTHING;
CREATE OR REPLACE FUNCTION public.has_company_permission(_company_id uuid,_tool text,_action text DEFAULT 'read') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT private.is_superadmin() OR EXISTS(SELECT 1 FROM public.user_company_permissions m JOIN public.profiles p ON p.user_id=m.user_id WHERE m.user_id=auth.uid() AND p.status='active' AND (_company_id IS NULL OR m.company_id=_company_id) AND CASE WHEN m.permissions->>'version'='1' THEN coalesce((m.permissions->'sub_modules'->>_tool)::boolean,false) AND coalesce((m.permissions->'actions'->_tool->>_action)::boolean,false) AND coalesce((m.permissions->'categories'->>(CASE WHEN _tool IN ('portal_empresa','portal_resultados') THEN 'portal' WHEN _tool LIKE 'indicadores_%' THEN 'indicadores' WHEN _tool LIKE 'pop_%' THEN 'pop' WHEN _tool LIKE 'horas_%' THEN 'horas' WHEN _tool IN ('faturamentos','pagamentos','relatorios_faturamento') THEN 'financeiro' WHEN _tool LIKE 'crm_%' THEN 'crm' WHEN _tool LIKE 'chamados_%' THEN 'chamados' ELSE 'gestao' END))::boolean,false) ELSE coalesce((m.permissions->>(CASE WHEN _tool IN ('portal_empresa','portal_resultados') THEN 'portal' WHEN _tool LIKE 'indicadores_%' THEN 'indicadores' WHEN _tool LIKE 'pop_%' THEN 'pop' WHEN _tool LIKE 'horas_%' THEN 'horas' WHEN _tool IN ('faturamentos','pagamentos','relatorios_faturamento') THEN 'financeiro' WHEN _tool LIKE 'crm_%' THEN 'crm' WHEN _tool LIKE 'chamados_%' THEN 'chamados' ELSE 'gestao' END))::boolean,false) END) $$;
REVOKE ALL ON FUNCTION public.has_company_permission(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_company_permission(uuid,text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION private.has_tool(_company_id uuid,_tool text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_superadmin() OR EXISTS(SELECT 1 FROM public.user_company_permissions m JOIN public.profiles p ON p.user_id=m.user_id WHERE m.user_id=auth.uid() AND m.company_id=_company_id AND p.status='active' AND CASE WHEN m.permissions->>'version'='1' THEN coalesce((m.permissions->'categories'->>_tool)::boolean,false) ELSE coalesce((m.permissions->>_tool)::boolean,false) END) $$;
CREATE OR REPLACE FUNCTION private.has_any_tool(_tool text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_superadmin() OR EXISTS(SELECT 1 FROM public.user_company_permissions m JOIN public.profiles p ON p.user_id=m.user_id WHERE m.user_id=auth.uid() AND p.status='active' AND CASE WHEN m.permissions->>'version'='1' THEN coalesce((m.permissions->'categories'->>_tool)::boolean,false) ELSE coalesce((m.permissions->>_tool)::boolean,false) END) $$;
CREATE OR REPLACE FUNCTION private.has_company_access(_company_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_superadmin() OR EXISTS(SELECT 1 FROM public.user_company_permissions m JOIN public.profiles p ON p.user_id=m.user_id WHERE m.user_id=auth.uid() AND m.company_id=_company_id AND p.status='active') $$;
CREATE OR REPLACE FUNCTION public.save_company_permissions(_user_id uuid,_company_id uuid,_role text,_permissions jsonb,_grant_superadmin boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE old_permissions jsonb; legacy jsonb;
BEGIN
IF NOT private.is_superadmin() THEN RAISE EXCEPTION 'Acesso restrito ao SuperAdmin'; END IF;
IF _role NOT IN ('CLIENTE','CONSULTOR','GESTOR','SUPERADMIN') OR _permissions->>'version' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'Matriz de acesso inválida'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_user_id) THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF;
IF _role='SUPERADMIN' AND NOT _grant_superadmin AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND is_superadmin) THEN RAISE EXCEPTION 'Confirme a concessão global de SuperAdmin'; END IF;
SELECT permissions INTO old_permissions FROM public.user_company_permissions WHERE user_id=_user_id AND company_id=_company_id FOR UPDATE;
INSERT INTO public.user_company_permissions(user_id,company_id,role,permissions) VALUES(_user_id,_company_id,_role,_permissions) ON CONFLICT(user_id,company_id) DO UPDATE SET role=EXCLUDED.role,permissions=EXCLUDED.permissions,updated_at=now();
legacy:=coalesce(_permissions->'categories','{}'::jsonb);
INSERT INTO public.company_members(user_id,company_id,member_role,permissions) VALUES(_user_id,_company_id,CASE WHEN _role IN ('SUPERADMIN','GESTOR') THEN 'gestor' WHEN _role='CLIENTE' THEN 'cliente' ELSE 'consultor' END,legacy) ON CONFLICT(user_id,company_id) DO UPDATE SET member_role=EXCLUDED.member_role,permissions=EXCLUDED.permissions;
IF _grant_superadmin THEN
INSERT INTO public.user_roles(user_id,role,is_superadmin) VALUES(_user_id,'admin',true) ON CONFLICT(user_id,role) DO UPDATE SET is_superadmin=true;
UPDATE public.profiles SET is_superadmin=true,status='active' WHERE user_id=_user_id;
END IF;
INSERT INTO public.audit_log(actor_id,action,entity,company_id,details) VALUES(auth.uid(),'granular_permissions_change','user_company_permissions',_company_id,jsonb_build_object('user_id',_user_id,'role',_role,'before',old_permissions,'after',_permissions,'global_superadmin_granted',_grant_superadmin));
END $$;
REVOKE ALL ON FUNCTION public.save_company_permissions(uuid,uuid,text,jsonb,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_company_permissions(uuid,uuid,text,jsonb,boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.remove_company_permissions(_user_id uuid,_company_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.is_superadmin() THEN RAISE EXCEPTION 'Acesso restrito ao SuperAdmin'; END IF; DELETE FROM public.user_company_permissions WHERE user_id=_user_id AND company_id=_company_id; DELETE FROM public.company_members WHERE user_id=_user_id AND company_id=_company_id; INSERT INTO public.audit_log(actor_id,action,entity,company_id,details) VALUES(auth.uid(),'company_access_removed','user_company_permissions',_company_id,jsonb_build_object('user_id',_user_id)); END $$;
REVOKE ALL ON FUNCTION public.remove_company_permissions(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.remove_company_permissions(uuid,uuid) TO authenticated,service_role;